def _j_cut(tag, cut):
    """FGH_PAGE with `tag` cut in two after the text `cut`: (the part up to and including it, the rest)."""
    page = FGH_PAGE % tag
    i = page.index(cut) + len(cut)
    return page[:i], page[i:]


