def _aw_module(tag, swap=None):
    """aww's module, or with one (old, new) swap in its head or its _send (each anchor once)."""
    head, send = AW_HEAD, AW_SEND
    if swap is not None:
        old, new = swap
        if old in head: head = head.replace(old, new, 1)
        elif send.count(old) == 1: send = send.replace(old, new, 1)
        else: raise ValueError("no swap anchor %r" % old)
    return _a_module(tag, send, head=head, call='return self._send(200, "%s", "text/html")' % (AW_PAGE % tag))


